mapper.select:
select ht.*, IFNULL( SUM( IF ( ht.`holidayType` = 'MATERNITY_LEAVE', IF (( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'MATERNITY_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 )), 0 ) AS maternityLeave, IFNULL( SUM( IF ( ht.`holidayType` = 'COMPENSATORY_LEAVE', IF (( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'COMPENSATORY_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 )), 0 ) compensatoryLeave, IFNULL( SUM( IF ( ht.`holidayType` = 'PATERNITY_LEAVE', IF (( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'PATERNITY_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 )), 0 ) paternityLeave, IFNULL( SUM( IF ( ht.`holidayType` = 'BEREAVEMENT_LEAVE', IF (( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'BEREAVEMENT_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 )), 0 ) bereavementLeave, IFNULL( SUM( IF ( ht.`holidayType` = 'COMPASSIONATE_LEAVE', IF (( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'COMPASSIONATE_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 )), 0 ) compassionateLeave, IFNULL( SUM( IF ( ht.`holidayType` = 'MARRIAGE_LEAVE', IF (( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'MARRIAGE_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 )), 0 ) marriageLeave, IFNULL( SUM( IF ( ht.`holidayType` = 'SICK_LEAVE', IF (( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'SICK_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 )), 0 ) sickLeave, IFNULL( SUM( IF ( ht.`holidayType` = 'ANNUAL_LEAVE', IF ( ( SELECT is_need_limit_quota FROM holiday_type WHERE type = 'ANNUAL_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.remain_balance ), 0 ) ), 0 ) annualLeave from ( SELECT hur.`id`, hur.`user_id` userId, ht.`type` holidayType, hur.`time_of_induction`, hur.`employee_organization` organizationId, hur.`attendance_group_id_of_arrange` attendanceGroupId, hur.`employee_name` employeeName FROM `holiday_balance_list` hur LEFT JOIN `holiday_type` ht ON ht.id = hur.holiday_type_id LEFT JOIN `holiday_balance` hb ON hur.`user_id` = hb.`user_id` WHERE hur.`show` = 1
and hur.`time_of_induction` between #{query.timeOfInduction.begin} and #{query.timeOfInduction.end}
and hur.`employee_name` like concat('%',#{query.keyword},'%')
and hur.`employee_organization` = #{query.organizationId}
and hur.`attendance_group_id_of_arrange` = #{query.attendanceGroupId}
GROUP BY hur.`user_id`,ht.`type` ) ht
LEFT JOIN `holiday_balance` hb ON hb.`user_id` = ht.`userId` and ht.`holidayType` = hb.`holiday_type`
GROUP BY ht.`userId`

SELECT hb.`user_id` `userId`, hur.`employee_name` `employeeName`, hb.`holiday_type` `holidayType`, SUM(IF(hb.`holiday_type`='MATERNITY_LEAVE',hb.`remain_balance`,0)) as maternityLeave , SUM(IF(hb.`holiday_type`='COMPENSATORY_LEAVE',hb.`remain_balance`,0)) as compensatoryLeave , SUM(IF(hb.`holiday_type`='PATERNITY_LEAVE',hb.`remain_balance`,0)) as paternityLeave, SUM(IF(hb.`holiday_type`='BEREAVEMENT_LEAVE',hb.`remain_balance`,0)) as bereavementLeave, SUM(IF(hb.`holiday_type`='COMPASSIONATE_LEAVE',hb.`remain_balance`,0)) as compassionateLeave, SUM(IF(hb.`holiday_type`='MARRIAGE_LEAVE',hb.`remain_balance`,0)) as marriageLeave, SUM(IF(hb.`holiday_type`='SICK_LEAVE',hb.`remain_balance`,0)) as sickLeave, SUM(IF(hb.`holiday_type`='ANNUAL_LEAVE',hb.`remain_balance`,0)) as annualLeave FROM `holiday_balance` hb where hb.`user_id` in
#{id}
GROUP BY hb.`user_id`

select ht.*, IFNULL( SUM( IF (( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'MATERNITY_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ) ), 0 ) AS `maternityLeave`, IFNULL( SUM( IF ( ht.`holidayType` = 'COMPENSATORY_LEAVE', IF (( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'COMPENSATORY_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ), 0 )), 0 ) `compensatoryLeave`, IFNULL( SUM( IF ( ht.`holidayType` = 'PATERNITY_LEAVE', IF (( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'PATERNITY_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ), 0 )), 0 ) `paternityLeave`, IFNULL( SUM( IF ( ht.`holidayType` = 'BEREAVEMENT_LEAVE', IF (( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'BEREAVEMENT_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ), 0 )), 0 ) `bereavementLeave`, IFNULL( SUM( IF ( ht.`holidayType` = 'COMPASSIONATE_LEAVE', IF (( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'COMPASSIONATE_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ), 0 )), 0 ) `compassionateLeave`, IFNULL( SUM( IF ( ht.`holidayType` = 'MARRIAGE_LEAVE', IF (( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'MARRIAGE_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ), 0 )), 0 ) `marriageLeave`, IFNULL( SUM( IF ( ht.`holidayType` = 'SICK_LEAVE', IF (( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'SICK_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ), 0 )), 0 ) `sickLeave`, IFNULL( SUM( IF ( ht.`holidayType` = 'ANNUAL_LEAVE', IF ( ( SELECT `is_need_limit_quota` FROM `holiday_type` WHERE `type` = 'ANNUAL_LEAVE' AND tenant = #{tenant} AND deleted = 0 ) = 1, 0, hb.`remain_balance` ), 0 ) ), 0 ) `annualLeave` from ( SELECT hur.`id`, hur.`user_id` `userId`, ht.`type` `holidayType`, hur.`time_of_induction`, hur.`employee_organization` `organizationId`, hur.`attendance_group_id_of_arrange` `attendanceGroupId`, hur.`employee_name` `employeeName` FROM `holiday_balance_list` hur LEFT JOIN `holiday_type` ht ON ht.`id` = hur.`holiday_type_id` LEFT JOIN `holiday_balance` hb ON hur.`user_id` = hb.`user_id` WHERE hur.`show` = 1
and hur.`time_of_induction` between #{query.timeOfInduction.begin} and #{query.timeOfInduction.end}
and hur.`employee_name` like concat('%',#{query.keyword},'%')
and hur.`employee_organization` = #{query.organizationId}
and hur.`attendance_group_id_of_arrange` = #{query.attendanceGroupId}
GROUP BY `hur`.`user_id`,`ht`.`type` ) ht
LEFT JOIN holiday_balance hb ON hb.`user_id` = ht.`userId` and ht.`holidayType` = hb.`holiday_type`
GROUP BY ht.`userId`
